# Cerberus Agent __VERSION__ (__PROFILE__) one-line installer, generated by the release build. Do not edit.
# Server: elevated PowerShell. Desktop: PowerShell that is not elevated; Windows asks for approval during setup.
#   irm <url of this file> | iex
# Download and verify only: & ([scriptblock]::Create((irm <url of this file>))) -DownloadOnly
# The MSI below must match the length and SHA-256 published with this release. It opens with its own UI.
& {
  param([switch]$DownloadOnly)
  $ErrorActionPreference = 'Stop'
  $ProgressPreference = 'SilentlyContinue'
  $version = '__VERSION__'
  $buildProfile = '__PROFILE__'
  $url = '__ARTIFACT_URL__'
  $sha256 = '__SHA256__'
  $length = [long]'__LENGTH__'

  $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
  $admin = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
  if (-not $DownloadOnly) {
    if ($buildProfile -eq 'server' -and -not $admin) { throw 'Run PowerShell as Administrator to install the Cerberus Server Agent.' }
    # An elevated installer would also start the agent window elevated.
    if ($buildProfile -eq 'desktop' -and $admin) { throw 'Run this in a PowerShell window that is not elevated. Windows asks for approval during setup.' }
    if (-not [Environment]::UserInteractive) { throw 'The installer needs an interactive desktop session.' }
  }
  [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

  # Elevated: a new folder directly under Program Files, where only administrators can create or rename folders.
  # Paths come from the system, not from environment variables.
  $root = if ($admin) { [Environment]::GetFolderPath('ProgramFiles') } else { [IO.Path]::GetTempPath() }
  $dir = Join-Path $root ('Cerberus.Install.' + [guid]::NewGuid().ToString('N'))
  $null = New-Item -ItemType Directory -Path $dir  # fails when anything already has this name
  $folder = Get-Item -LiteralPath $dir -Force
  if (-not $folder.PSIsContainer -or ($folder.Attributes -band [IO.FileAttributes]::ReparsePoint) -or
      @(Get-ChildItem -LiteralPath $dir -Force).Count -ne 0) { throw "Download folder is not a new empty folder: $dir" }
  if ($admin) {
    # Only Administrators and SYSTEM may open the download folder.
    $acl = New-Object Security.AccessControl.DirectorySecurity
    $acl.SetAccessRuleProtection($true, $false)
    foreach ($sid in 'S-1-5-32-544', 'S-1-5-18') {
      $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule(
        (New-Object Security.Principal.SecurityIdentifier($sid)), 'FullControl', 'ContainerInherit, ObjectInherit', 'None', 'Allow')))
    }
    Set-Acl -LiteralPath $dir -AclObject $acl
  }

  $msi = Join-Path $dir ([IO.Path]::GetFileName(([Uri]$url).AbsolutePath))
  $log = Join-Path $dir 'install.log'
  $keepMsi = $false
  $keepLog = $false
  try {
    Write-Host "Downloading Cerberus Agent $version ..."
    Invoke-WebRequest -Uri $url -OutFile $msi -UseBasicParsing
    # The read lock blocks writes, renames and deletes of the verified file until msiexec has finished.
    $stream = [IO.File]::Open($msi, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
    try {
      if ($stream.Length -ne $length) { throw "Downloaded installer has $($stream.Length) bytes, expected $length." }
      $hasher = [Security.Cryptography.SHA256]::Create()
      try { $actual = ([BitConverter]::ToString($hasher.ComputeHash($stream)) -replace '-', '').ToLowerInvariant() } finally { $hasher.Dispose() }
      if ($actual -cne $sha256) { throw 'Downloaded installer does not match the published SHA-256.' }
      if ($DownloadOnly) { $keepMsi = $true; Write-Host "Verified: $msi"; return }
      Write-Host "Opening the Cerberus Agent $version installer ..."
      $msiexec = Join-Path ([Environment]::GetFolderPath('System')) 'msiexec.exe'
      $process = Start-Process -FilePath $msiexec -PassThru -ArgumentList @('/i', ('"{0}"' -f $msi), '/l*v', ('"{0}"' -f $log))
      $null = $process.Handle  # keeps the exit code readable
      # Waits for msiexec only; the agent window it may open keeps running.
      $process.WaitForExit()
      $code = $process.ExitCode
    } finally {
      $stream.Dispose()
    }
    if ($code -eq 0) { Write-Host "Cerberus Agent $version installed." }
    elseif ($code -eq 3010 -or $code -eq 1641) { Write-Host "Cerberus Agent $version installed. Restart Windows to finish." }
    elseif ($code -eq 1602) { Write-Host 'Installation cancelled.' }
    else { $keepLog = $true; throw "Installer exited with code $code. Log: $log" }
  } finally {
    if (-not $keepMsi) { Remove-Item -LiteralPath $msi -Force -ErrorAction SilentlyContinue }
    if (-not $keepLog) { Remove-Item -LiteralPath $log -Force -ErrorAction SilentlyContinue }
    if (-not $keepMsi -and -not $keepLog) { try { [IO.Directory]::Delete($dir, $false) } catch { Write-Host "Could not remove $dir" } }
  }
} @args
